// ==============================
// COST DATA FROM WORKFLOW 1
// ==============================

const costData        = $('Receive Cost Data').first().json.body;
const makeReport      = costData.makeReport;
const vapiReport      = costData.vapiReport;
const twilioReport    = costData.twilioReport;
const voiceflowReport = costData.voiceflowReport;


// ==============================
// MANUAL SUBSCRIPTION COSTS
// ── ONLY CHANGE THESE VALUES ──
// When you upgrade a plan, update
// the monthly USD cost below.
// Everything else calculates itself.
// ==============================

const MAKE_MONTHLY_USD      = 0;  // Free=0, Core=$9, Pro=$16
const VOICEFLOW_MONTHLY_USD = 0;  // Starter=0, Teams=$80

// Daily cost = monthly fee / days in current month
const daysInMonth = new Date(
  new Date().getFullYear(),
  new Date().getMonth() + 1,
  0
).getDate();

const makeDailyCost      = MAKE_MONTHLY_USD      / daysInMonth;
const voiceflowDailyCost = VOICEFLOW_MONTHLY_USD / daysInMonth;


// ==============================
// TOTAL COST (ALL 4 PLATFORMS)
// ==============================

const vapiCost   = Number(vapiReport.totalCost   || 0); // real USD from API
const twilioCost = Number(twilioReport.totalCost  || 0); // real USD from API

const totalCostUSD =
  vapiCost        +   // usage-based, from API
  twilioCost      +   // usage-based, from API
  makeDailyCost   +   // subscription, manual
  voiceflowDailyCost; // subscription, manual

// Convert full cost to INR for ROI comparison
// Update this rate if INR/USD changes significantly
const USD_TO_INR   = 96.36;
const totalCostINR = totalCostUSD * USD_TO_INR;


// ==============================
// LEAD DATA FROM SHEET
// ==============================

const leads = $('Get All leads').all().map(i => i.json);
const today = new Date().toISOString().split('T')[0];


// ==============================
// COUNTERS
// ==============================

let totalLeads         = 0;
let newLeadsToday      = 0;
let contactedLeads     = 0;
let qualifiedLeads     = 0;
let opportunityLeads   = 0;
let meetingScheduled   = 0;
let wonLeads           = 0;
let lostLeads          = 0;
let bookedAppointments = 0;
let totalLeadScore     = 0;
let whatsappSent       = 0;
let whatsappSkipped    = 0;

// Won lead budget parsing — INR only
let wonRevenueMin = 0;
let wonRevenueMax = 0;

const pipelineStats = {
  'Contacted':         0,
  'Qualified':         0,
  'Opportunity':       0,
  'Meeting Scheduled': 0,
  'Won':               0,
  'Lost':              0,
  'Unknown':           0
};

const channelStats = {};
const sourceStats  = {};


// ==============================
// LOOP THROUGH LEADS
// ==============================

for (const lead of leads) {

  totalLeads++;
  totalLeadScore += Number(lead['Lead score'] || 0);

  // New today
  const entryDate = String(lead['Lead Entry'] || '');
  if (entryDate.startsWith(today)) newLeadsToday++;

  // Channel
  let channel = lead.Channel || 'Unknown';
  // Replace Website Form with Social Media
  if (channel === 'Website Form') {
  channel = 'Social Media';
  }
  if (!channelStats[channel]) {
    channelStats[channel] = {
      total: 0, contacted: 0, qualified: 0,
      opportunity: 0, meetingScheduled: 0,
      won: 0, lost: 0, booked: 0
    };
  }
  channelStats[channel].total++;

  // Source
  const source = lead.Source || 'Unknown';
  if (!sourceStats[source]) sourceStats[source] = 0;
  sourceStats[source]++;

  // WhatsApp
  const wa = (lead.Whatsapp_Status || '').trim().toLowerCase();
  if (wa === 'sent')    whatsappSent++;
  if (wa === 'skipped') whatsappSkipped++;

  // Appointment
  const appt = (lead.Appointment_Status || '').trim().toLowerCase();
  if (appt === 'booked') {
    bookedAppointments++;
    channelStats[channel].booked++;
  }

  // Pipeline stage
  const stage = (lead.Pipeline_stage || '').trim();
  if (pipelineStats.hasOwnProperty(stage)) {
    pipelineStats[stage]++;
  } else {
    pipelineStats['Unknown']++;
  }

  switch (stage) {
    case 'Contacted':
      contactedLeads++;
      channelStats[channel].contacted++;
      break;
    case 'Qualified':
      qualifiedLeads++;
      channelStats[channel].qualified++;
      break;
    case 'Opportunity':
      opportunityLeads++;
      channelStats[channel].opportunity++;
      break;
    case 'Meeting Scheduled':
      meetingScheduled++;
      channelStats[channel].meetingScheduled++;
      break;
    case 'Won':
      wonLeads++;
      channelStats[channel].won++;
      break;
    case 'Lost':
      lostLeads++;
      channelStats[channel].lost++;
      break;
  }


  // ==============================
  // BUDGET PARSING — WON LEADS ONLY
  // Only Won leads count toward
  // revenue estimate for ROI
  // ==============================

  if (stage === 'Won') {

    const raw = String(lead.Budget || '').trim();

    // Detect currency
    const isUSD = raw.includes('$');
    const isINR = raw.includes('₹') || (!isUSD && /\d/.test(raw));

    // Clean and expand shorthand
    const cleaned = raw
      .replace(/[₹$,+\s]/g, '')
      .replace(/k/gi,   '000')
      .replace(/l/gi,   '00000');

    const nums = cleaned.match(/\d+/g);

    if (nums && nums.length >= 1) {

      let min = Number(nums[0]);
      let max = Number(nums[nums.length - 1]);

      // Convert USD to INR so everything
      // is in the same currency
      if (isUSD) {
        min = min * USD_TO_INR;
        max = max * USD_TO_INR;
      }

      wonRevenueMin += min;
      wonRevenueMax += max;
    }
  }
}


// ==============================
// ROI CALCULATIONS
// ==============================

const avgLeadScore = totalLeads > 0
  ? (totalLeadScore / totalLeads).toFixed(1)
  : '0';

// Cost metrics
const costPerLead = totalLeads > 0 && totalCostINR > 0
  ? (totalCostINR / totalLeads).toFixed(2)
  : '0.00';

const costPerQualified = qualifiedLeads > 0 && totalCostINR > 0
  ? (totalCostINR / qualifiedLeads).toFixed(2)
  : '0.00';

const costPerMeeting = meetingScheduled > 0 && totalCostINR > 0
  ? (totalCostINR / meetingScheduled).toFixed(2)
  : '0.00';

const costPerWon = wonLeads > 0 && totalCostINR > 0
  ? (totalCostINR / wonLeads).toFixed(2)
  : '0.00';

// Conversion rates
const leadToQualifiedRate = totalLeads > 0
  ? ((qualifiedLeads / totalLeads) * 100).toFixed(1) + '%'
  : '0%';

const leadToMeetingRate = totalLeads > 0
  ? ((meetingScheduled / totalLeads) * 100).toFixed(1) + '%'
  : '0%';

const meetingToWonRate = meetingScheduled > 0
  ? ((wonLeads / meetingScheduled) * 100).toFixed(1) + '%'
  : '0%';

const overallConversionRate = totalLeads > 0
  ? ((wonLeads / totalLeads) * 100).toFixed(1) + '%'
  : '0%';

// Revenue from Won leads only (all converted to INR)
const wonRevenueMid = (wonRevenueMin + wonRevenueMax) / 2;

// Estimated ROI — based on Won lead budgets vs total cost
// Both in INR
let estimatedROI = 'N/A';
let estimatedROINote = '';

if (wonLeads === 0) {
  estimatedROINote = 'No won leads yet';
} else if (totalCostINR === 0) {
  estimatedROINote = 'No platform cost recorded yet';
  // Still show revenue signal even without cost
  estimatedROI = 'Cost = ₹0, Revenue signal = ₹' +
    wonRevenueMid.toLocaleString('en-IN');
} else {
  const roi = ((wonRevenueMid - totalCostINR) / totalCostINR) * 100;
  estimatedROI     = roi.toFixed(1) + '%';
  estimatedROINote =
    'Based on Won lead budget midpoints converted to INR vs total platform cost in INR';
}


// ==============================
// MAKE OPS BURN RATE
// ==============================

const makeOpsBurnRate = makeReport.operationsLimit > 0
  ? ((makeReport.operationsUsed / makeReport.operationsLimit) * 100).toFixed(1) + '%'
  : '0%';

const daysToReset = makeReport.nextReset
  ? Math.ceil(
      (new Date(makeReport.nextReset) - new Date()) /
      (1000 * 60 * 60 * 24)
    )
  : 0;


// ==============================
// CHANNEL BREAKDOWN
// ==============================

const channelBreakdown = Object.entries(channelStats).map(([ch, s]) => ({
  channel:          ch,
  totalLeads:       s.total,
  contacted:        s.contacted,
  qualified:        s.qualified,
  opportunity:      s.opportunity,
  meetingScheduled: s.meetingScheduled,
  won:              s.won,
  lost:             s.lost,
  bookedAppts:      s.booked,
  conversionRate:   s.total > 0
    ? ((s.won / s.total) * 100).toFixed(1) + '%'
    : '0%'
}));

const bestChannel = [...channelBreakdown]
  .sort((a, b) => parseFloat(b.conversionRate) - parseFloat(a.conversionRate))
  [0]?.channel || 'N/A';


// ==============================
// SOURCE BREAKDOWN
// ==============================

const sourceBreakdown = Object.entries(sourceStats)
  .map(([source, count]) => ({ source, count }))
  .sort((a, b) => b.count - a.count);


// ==============================
// PIPELINE FUNNEL
// ==============================

const pipelineOrder = [
  'Contacted', 'Qualified', 'Opportunity',
  'Meeting Scheduled', 'Won', 'Lost', 'Unknown'
];

const pipelineBreakdown = pipelineOrder
  .filter(s => pipelineStats[s] > 0)
  .map(s => ({
    stage:          s,
    count:          pipelineStats[s],
    percentOfTotal: totalLeads > 0
      ? ((pipelineStats[s] / totalLeads) * 100).toFixed(1) + '%'
      : '0%'
  }));


// ==============================
// RETURN ROI REPORT
// ==============================

return [{
  json: {
    roiReport: {

      reportDate:  today,
      generatedAt: new Date().toISOString(),

      // ── Platform costs (all 4) ──
      platformCosts: {

        // Usage-based (from API)
        vapiCost_USD:          vapiCost.toFixed(4),
        twilioCost_USD:        twilioCost.toFixed(4),

        // Subscription-based (manual config)
        makeCost_USD:          makeDailyCost.toFixed(4),
        voiceflowCost_USD:     voiceflowDailyCost.toFixed(4),

        // Totals
        totalCost_USD:         totalCostUSD.toFixed(4),
        totalCost_INR:         totalCostINR.toFixed(2),
        exchangeRateUsed:      `1 USD = ₹${USD_TO_INR}`,

        // Make.com usage context
        makeOperationsUsed:    makeReport.operationsUsed,
        makeOperationsLimit:   makeReport.operationsLimit,
        makeOpsBurnRate,
        makeDaysToReset:       daysToReset,
        makeCreditsUsed:       makeReport.creditsUsed,

        // Voiceflow usage context
        voiceflowAIOperations: voiceflowReport.totalAIOperations,
        voiceflowInteractions: voiceflowReport.totalInteractions,
        voiceflowTopModel:     voiceflowReport.mostUsedModel,

        // Vapi usage context
        vapiTotalCalls:        vapiReport.totalCalls,
        vapiAvgCallDuration:   vapiReport.avgCallDuration,
        vapiCostBreakdown:     vapiReport.costBreakdown
      },

      // ── Lead funnel ──
      funnel: {
        totalLeads,
        newLeadsToday,
        contactedLeads,
        qualifiedLeads,
        opportunityLeads,
        meetingScheduled,
        wonLeads,
        lostLeads,
        bookedAppointments,
        avgLeadScore,
        whatsappSent,
        whatsappSkipped
      },

      // ── ROI (all in INR) ──
      roi: {
        currency:              'INR',
        totalCostINR:          totalCostINR.toFixed(2),
        costPerLead_INR:       costPerLead,
        costPerQualified_INR:  costPerQualified,
        costPerMeeting_INR:    costPerMeeting,
        costPerWon_INR:        costPerWon,
        overallConversionRate,
        estimatedROI,
        estimatedROINote
      },

      // ── Revenue from Won leads only ──
      wonLeadRevenue: {
        currency:       'INR',
        note:           'Budget range of Won leads only, USD budgets converted at ₹' + USD_TO_INR,
        wonLeadCount:   wonLeads,
        revenueMin_INR: wonRevenueMin,
        revenueMax_INR: wonRevenueMax,
        revenueMid_INR: Math.round(wonRevenueMid)
      },

      // ── Conversion rates ──
      conversionRates: {
        leadToQualifiedRate,
        leadToMeetingRate,
        meetingToWonRate,
        overallConversionRate
      },

      // ── Breakdowns ──
      pipelineBreakdown,
      channelBreakdown,
      bestChannel,
      sourceBreakdown
    }
  }
}];

// ==========================================
// SIMPLE EXECUTIVE ROI EMAIL REPORT
